<script>
(()=>{const list=document.getElementById('home-section-list'),order=document.getElementById('home_sections_order');if(!list||!order)return;const sync=()=>order.value=Array.from(list.children).map(x=>x.dataset.section).join(',');list.addEventListener('click',e=>{const b=e.target.closest('[data-move]');if(!b)return;const row=b.closest('li'),prev=row.previousElementSibling,next=row.nextElementSibling;if(b.dataset.move==='up'&&prev)list.insertBefore(row,prev);if(b.dataset.move==='down'&&next)list.insertBefore(next,row);sync()});let moving=null;list.addEventListener('dragstart',e=>{moving=e.target.closest('li');if(moving){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',moving.dataset.section)}});list.addEventListener('dragover',e=>{e.preventDefault();const over=e.target.closest('li');if(!over||!moving||over===moving)return;const r=over.getBoundingClientRect();list.insertBefore(moving,e.clientY<r.top+r.height/2?over:over.nextElementSibling)});list.addEventListener('dragend',()=>{moving=null;sync()});sync()})();

</script>

<style>.a-home-section-list{display:grid;gap:8px;padding:0;list-style:none}.a-home-section{display:grid;grid-template-columns:22px minmax(150px,1fr) auto auto;gap:12px;align-items:center;padding:12px;border:1px solid #e7e8e1;border-radius:12px;background:#fff}.a-home-section[draggable="true"]{cursor:grab}.a-home-section small{display:block;margin-top:3px;color:#788078;font-size:10px}.a-home-grip{color:#a4aaa1;font-size:19px}.a-home-order{display:flex;gap:5px}@media(max-width:600px){.a-home-section{grid-template-columns:20px 1fr auto}.a-home-order{grid-column:2/-1;justify-self:end}}</style>
<style>.a-module-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:11px;margin:14px 0 23px}.a-module-card{display:flex;align-items:flex-start;gap:12px;padding:15px;border:1px solid #e7e8e1;border-radius:14px;background:#fff;cursor:pointer}.a-module-card>span:last-child{display:grid;gap:5px}.a-module-card b{color:#303831;font-size:12px;font-weight:850}.a-module-card small{color:#778177;font-size:10px;line-height:1.55}.a-module-card em{color:#39814d;font-size:9px;font-style:normal;font-weight:850}.a-module-switch{position:relative;flex:none;width:37px;height:22px}.a-module-switch input{position:absolute;width:1px;height:1px;opacity:0}.a-module-switch i{position:absolute;inset:0;border-radius:99px;background:#ccd2c9;transition:background .18s}.a-module-switch i:before{content:"";position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 3px #0002;transition:transform .18s}.a-module-switch input:checked+i{background:#48a064}.a-module-switch input:checked+i:before{transform:translateX(15px)}.a-module-switch input:focus-visible+i{outline:3px solid #ffb59a;outline-offset:2px}.a-module-card:has(input:not(:checked)) em{color:#a04d36}</style>
